CREATE OR REPLACE FUNCTION public.authorize_immomio_application_send(p_id uuid, p_token uuid, p_source_identifier uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare a public.applications%rowtype; target jsonb;
begin
 select * into a from public.applications where id=p_id for update;
 if not found or p_token is null or p_source_identifier is null or a.lease_token is distinct from p_token or a.lease_until is null or a.lease_until<=now() then return false; end if;
 select app_private.immomio_application_target(l.raw,l.canonical_url) into target from public.listings l where l.id=a.listing_id;
 if target->>'status' is distinct from 'resolved' or (target->>'source_identifier')::uuid is distinct from p_source_identifier then return false; end if;
 return public.begin_application_submission(p_id);
end $function$

CREATE OR REPLACE FUNCTION public.begin_application_submission(p_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  a public.applications%rowtype;
  l public.listings%rowtype;
  t jsonb;
  owner_id uuid;
  v_provider text;
  v_pref public.application_preferences%rowtype;
  v_local_now timestamp;
  v_local_date date;
  v_local_time time;
  v_iso_day smallint;
  v_used integer;
  v_window_ok boolean;
  v_next timestamptz;
begin
  select * into a from public.applications where id=p_id for update;
  if not found or a.status<>'pending' or a.submission_started_at is not null then
    return false;
  end if;

  select * into l from public.listings where id=a.listing_id;
  if not found then return false; end if;

  v_provider := app_private.application_provider_target(l.source_id,l.raw,l.canonical_url);

  select * into v_pref
  from public.application_preferences
  where user_id=a.user_id
  for update;

  if not found
     or not app_private.application_provider_preference_enabled(a.user_id,v_provider)
     or not exists(
       select 1
       from public.bot_users u
       join public.sources s on s.id=l.source_id
       where u.id=a.user_id
         and u.is_active
         and app_private.user_is_premium(u.id)
         and app_private.applicant_profile_identity_ready(u.id)
         and app_private.user_listing_matches_active_search(u.id,l.id)
         and app_private.application_target_ready(u.id,l.source_id,l.raw,l.canonical_url)
         and app_private.application_listing_auto_apply_allowed(l.title,l.property_type,l.raw)
         and l.is_active
         and coalesce(l.quality_status,'unchecked')<>'rejected'
         and coalesce(l.is_primary_listing,false)
         and s.enabled
         and s.runtime_mode='live'
         and s.delivery_mode='live'
         and l.source_id=a.source_id
         and app_private.delivery_newness_qualified(l.id,statement_timestamp())
         and exists(
           select 1
           from public.delivery_events d
           where d.listing_id=l.id
             and d.recipient_user_id=u.id
             and d.event_type='new_listing'
             and (
               (d.channel='telegram' and d.status in ('pending','processing','sent'))
               or (d.channel='web' and d.status='available')
             )
         )
     )
  then
    update public.applications
    set status='failed',last_error='not_eligible',wait_reason=null,lease_until=null
    where id=p_id;
    return false;
  end if;

  v_local_now := now() at time zone v_pref.timezone;
  v_local_date := v_local_now::date;
  v_local_time := v_local_now::time;
  v_iso_day := extract(isodow from v_local_now)::smallint;

  if not (v_iso_day = any(v_pref.allowed_weekdays)) then
    update public.applications
    set wait_reason='weekday_blocked',
        next_attempt_at=now()+interval '6 hours',
        lease_until=null
    where id=p_id;
    return false;
  end if;

  v_window_ok := true;
  if v_pref.send_window_start is not null then
    if v_pref.send_window_start <= v_pref.send_window_end then
      v_window_ok := v_local_time >= v_pref.send_window_start
                     and v_local_time <= v_pref.send_window_end;
    else
      v_window_ok := v_local_time >= v_pref.send_window_start
                     or v_local_time <= v_pref.send_window_end;
    end if;
  end if;

  if not v_window_ok then
    update public.applications
    set wait_reason='outside_send_window',
        next_attempt_at=now()+interval '15 minutes',
        lease_until=null
    where id=p_id;
    return false;
  end if;

  if v_pref.daily_limit is not null and a.quota_local_date is distinct from v_local_date then
    select count(*) into v_used
    from public.applications q
    where q.user_id=a.user_id
      and q.quota_local_date=v_local_date
      and q.id<>a.id;

    if v_used >= v_pref.daily_limit then
      v_next := ((v_local_date+1)::timestamp at time zone v_pref.timezone);
      update public.applications
      set wait_reason='daily_limit',
          next_attempt_at=v_next,
          lease_until=null
      where id=p_id;
      return false;
    end if;
  end if;

  t:=app_private.immomio_application_target(l.raw,l.canonical_url);
  if t->>'status'='resolved' then
    insert into app_private.application_send_keys(user_id,provider,source_identifier,application_id)
    values(a.user_id,'immomio',(t->>'source_identifier')::uuid,a.id)
    on conflict do nothing;

    select k.application_id into owner_id
    from app_private.application_send_keys k
    where k.user_id=a.user_id
      and k.provider='immomio'
      and k.source_identifier=(t->>'source_identifier')::uuid;

    if owner_id is distinct from a.id then
      update public.applications
      set status='manual_required',last_error='duplicate_provider_object',wait_reason=null,lease_until=null
      where id=p_id;
      return false;
    end if;
  end if;

  update public.applications
  set status='processing',
      attempts=attempts+1,
      submission_started_at=now(),
      quota_local_date=v_local_date,
      wait_reason=null
  where id=p_id;

  return true;
end
$function$

CREATE OR REPLACE FUNCTION public.claim_platform_connect_flow(p_flow uuid, p_user uuid, p_provider text)
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare v_flow public.platform_auth_flows%rowtype; v_claim text;
begin
  select * into v_flow from public.platform_auth_flows
  where id=p_flow and user_id=p_user and provider=p_provider;
  if not found then raise exception 'auth_flow_expired'; end if;
  -- Lock membership/assignment before the flow: assignment invalidation uses that order.
  perform app_private.assert_platform_connect_context(v_flow);
  select * into v_flow from public.platform_auth_flows
  where id=p_flow and user_id=p_user and provider=p_provider for update;
  if not found or v_flow.consumed_at is not null or v_flow.expires_at<=clock_timestamp()
     or v_flow.context ? 'completion_claim' then raise exception 'auth_flow_expired'; end if;
  v_claim:=encode(extensions.gen_random_bytes(24),'hex');
  update public.platform_auth_flows
  set context=coalesce(context,'{}'::jsonb)||jsonb_build_object('completion_claim',v_claim)
  where id=p_flow;
  return v_claim;
end $function$

CREATE OR REPLACE FUNCTION public.claim_platform_session(p_user uuid, p_source bigint, p_disconnect boolean DEFAULT false)
 RETURNS SETOF platform_sessions
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if p_user is null or p_source is null or p_source not in (1,2) or p_disconnect is null then return; end if;
 if not p_disconnect and not exists(select 1 from public.bot_users where id=p_user and is_active and app_private.user_is_premium(id)) then return; end if;
 insert into public.platform_sessions(user_id,source_id) values(p_user,p_source) on conflict do nothing;
 return query update public.platform_sessions set lease_token=gen_random_uuid(),lease_until=now()+interval '3 minutes',updated_at=now()
 where user_id=p_user and source_id=p_source and (lease_until is null or lease_until<now()) returning *;
end $function$

CREATE OR REPLACE FUNCTION public.claim_source_jobs(p_worker text, p_qty integer DEFAULT 3)
 RETURNS TABLE(job_id uuid, queue_msg_id bigint, source_id smallint, worker_slug text, attempt integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r record; v_job uuid; v_source smallint; v_attempt integer; v_status text; v_limit integer:=greatest(1,least(coalesce(p_qty,3),3));
begin
  for r in select * from pgmq.read('source_jobs',600,v_limit,'{}'::jsonb)
  loop
    begin v_job:=(r.message->>'job_id')::uuid; v_source:=(r.message->>'source_id')::smallint;
    exception when others then perform pgmq.archive('source_jobs',r.msg_id); continue; end;
    -- A worker that repeatedly dies must not hold one source forever.
    update public.source_jobs j
    set status='dead', error_message='Source job lease expired after five attempts',
        finished_at=now(), updated_at=now()
    where j.id=v_job and j.queue_msg_id=r.msg_id and j.status='processing'
      and j.attempts>=5 and j.updated_at<=now()-interval '10 minutes';
    if found then
      perform pgmq.archive('source_jobs', r.msg_id);
      continue;
    end if;
    update public.source_jobs j
    set status='processing',attempts=j.attempts+1,started_at=now(),worker='source-worker',updated_at=now()
    where j.id=v_job and j.queue_msg_id=r.msg_id and (j.status in ('enqueued','retry') or (j.status='processing' and j.updated_at <= now()-interval '10 minutes'))
    returning j.attempts into v_attempt;
    if found then
      job_id:=v_job; queue_msg_id:=r.msg_id; source_id:=v_source; worker_slug:='source-worker'; attempt:=v_attempt; return next;
    else
      select j.status into v_status from public.source_jobs j where j.id=v_job and j.queue_msg_id=r.msg_id;
      if v_status is distinct from 'processing' then perform pgmq.archive('source_jobs',r.msg_id); end if;
    end if;
  end loop;
end;$function$

CREATE OR REPLACE FUNCTION public.claim_stripe_webhook_event(p_event_id text, p_event_type text, p_event_created bigint)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_status text;
  v_updated_at timestamptz;
begin
  insert into public.stripe_webhook_events(
    event_id, event_type, event_created, status, attempts, updated_at
  ) values (
    p_event_id, p_event_type, p_event_created, 'processing', 1, now()
  )
  on conflict (event_id) do nothing;

  if found then
    return 'claimed';
  end if;

  select e.status, e.updated_at
    into v_status, v_updated_at
  from public.stripe_webhook_events e
  where e.event_id = p_event_id
  for update;

  if v_status = 'processed' then
    return 'duplicate';
  end if;
  if v_status = 'processing' and v_updated_at > now() - interval '10 minutes' then
    return 'busy';
  end if;

  update public.stripe_webhook_events
  set event_type = p_event_type,
      event_created = p_event_created,
      status = 'processing',
      attempts = attempts + 1,
      last_error = null,
      updated_at = now()
  where event_id = p_event_id;

  return 'claimed';
end;
$function$

CREATE OR REPLACE FUNCTION public.claim_telegram_update(p_payload jsonb)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_id bigint := (p_payload->>'update_id')::bigint;v_user bigint:=coalesce((p_payload#>>'{callback_query,from,id}')::bigint,(p_payload#>>'{message,from,id}')::bigint);v_attempt integer;
begin
 if v_id is null then raise exception 'missing update_id'; end if;
 perform pg_advisory_xact_lock(v_user);
 insert into public.bot_events(telegram_update_id,event_type,telegram_user_id,payload,processing_status)
 values(v_id,case when p_payload ? 'callback_query' then 'callback_query' else 'message' end,v_user,p_payload,'pending') on conflict(telegram_update_id) do nothing;
 if exists(select 1 from public.bot_events where telegram_user_id=v_user and telegram_update_id<>v_id and processing_status='processing' and processing_at>now()-interval '10 minutes') then return -1; end if;
 update public.bot_events set processing_status='processing',processing_attempt=processing_attempt+1,processing_at=now(),processing_error=null
 where telegram_update_id=v_id and (processing_status in ('pending','failed') or (processing_status='processing' and processing_at<now()-interval '10 minutes')) returning processing_attempt into v_attempt;
 if found then return v_attempt; end if;
 if exists(select 1 from public.bot_events where telegram_update_id=v_id and processing_status='done') then return 0;end if;
 return -1;
end $function$

CREATE OR REPLACE FUNCTION public.coach_adopt_participant(p_actor uuid, p_user uuid, p_coach uuid)
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_actor public.coaching_members%rowtype;
  v_public_id text;
begin
  select * into v_actor
  from public.coaching_members
  where id=p_actor and is_active
  for share;
  if not found or v_actor.role<>'admin' then raise exception 'admin_required'; end if;
  if not exists(
    select 1 from public.coaching_workspaces
    where id=v_actor.workspace_id and is_active and not operations_paused
  ) then raise exception 'workspace_unavailable'; end if;
  if p_coach is null or not exists(
    select 1 from public.coaching_members
    where id=p_coach and workspace_id=v_actor.workspace_id
      and is_active and role in ('coach','admin')
    for share
  ) then raise exception 'coach_unavailable'; end if;
  if not exists(select 1 from public.bot_users where id=p_user) then
    raise exception 'participant_unavailable';
  end if;
  if exists(select 1 from public.coaching_participants where user_id=p_user) then
    raise exception 'participant_already_assigned';
  end if;
  v_public_id := 'cp_'||encode(extensions.gen_random_bytes(12),'hex');
  insert into public.coaching_participants(
    user_id,workspace_id,coach_member_id,created_by_member_id,status,public_id
  ) values(p_user,v_actor.workspace_id,p_coach,v_actor.id,'active',v_public_id);
  insert into public.coaching_audit_events(
    workspace_id,actor_member_id,participant_user_id,action,changes
  ) values(
    v_actor.workspace_id,v_actor.id,p_user,'participant_adopted',
    jsonb_build_object('coach_member_id',p_coach,'preserved_existing_identity',true)
  );
  return v_public_id;
end
$function$

CREATE OR REPLACE FUNCTION public.coach_assign_unassigned_participant(p_actor uuid, p_user uuid, p_coach uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_actor public.coaching_members%rowtype;
  v_assignment public.coaching_participants%rowtype;
  v_updated integer;
begin
  select * into v_actor
  from public.coaching_members
  where id=p_actor and is_active
  for share;
  if not found or v_actor.role<>'admin' then raise exception 'admin_required'; end if;
  if not exists(
    select 1 from public.coaching_workspaces
    where id=v_actor.workspace_id and is_active and not operations_paused
  ) then raise exception 'workspace_unavailable'; end if;
  select * into v_assignment
  from public.coaching_participants
  where user_id=p_user and workspace_id=v_actor.workspace_id
  for update;
  if not found then raise exception 'participant_forbidden'; end if;
  if v_assignment.coach_member_id is not null then
    raise exception 'participant_already_assigned';
  end if;
  if p_coach is null or not exists(
    select 1 from public.coaching_members
    where id=p_coach and workspace_id=v_actor.workspace_id
      and is_active and role in ('coach','admin')
    for share
  ) then raise exception 'coach_unavailable'; end if;
  update public.coaching_participants
  set coach_member_id=p_coach,
      assignment_version=assignment_version+1,
      updated_at=now()
  where user_id=p_user and workspace_id=v_actor.workspace_id
    and coach_member_id is null;
  get diagnostics v_updated = row_count;
  if v_updated<>1 then raise exception 'participant_already_assigned'; end if;
  insert into public.coaching_audit_events(
    workspace_id,actor_member_id,participant_user_id,action,changes
  ) values(
    v_actor.workspace_id,v_actor.id,p_user,'participant_assigned',
    jsonb_build_object('from',null,'to',p_coach,'source','telegram_import')
  );
  return true;
end
$function$

CREATE OR REPLACE FUNCTION public.coach_change_member_role(p_actor uuid, p_member uuid, p_role text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_actor public.coaching_members%rowtype;
  v_member public.coaching_members%rowtype;
  v_role text;
  v_is_super_admin boolean;
  v_old_role text;
  v_old_is_super_admin boolean;
  v_active_super_admins integer;
begin
  case lower(btrim(coalesce(p_role,'')))
    when 'super_admin' then
      v_role='admin';
      v_is_super_admin=true;
    when 'admin' then
      v_role='admin';
      v_is_super_admin=false;
    when 'manager' then
      v_role='coach';
      v_is_super_admin=false;
    when 'coach' then
      v_role='coach';
      v_is_super_admin=false;
    else
      raise exception 'invalid_member_role';
  end case;

  select * into v_actor
  from public.coaching_members
  where id=p_actor
    and is_active
  for share;

  if not found
     or v_actor.role<>'admin'
     or v_actor.is_super_admin is not true
  then
    raise exception 'member_management_forbidden';
  end if;

  if p_actor=p_member then
    raise exception 'super_admin_protected';
  end if;

  select * into v_member
  from public.coaching_members
  where id=p_member
    and workspace_id=v_actor.workspace_id
  for update;

  if not found then
    raise exception 'member_management_forbidden';
  end if;

  v_old_role=v_member.role;
  v_old_is_super_admin=(v_member.is_super_admin is true);

  if v_old_is_super_admin and not v_is_super_admin then
    select count(*) into v_active_super_admins
    from public.coaching_members
    where workspace_id=v_actor.workspace_id
      and is_active
      and is_super_admin is true;
    if v_active_super_admins<=1 then
      raise exception 'super_admin_required';
    end if;
  end if;

  if v_old_role=v_role and v_old_is_super_admin=v_is_super_admin then
    return jsonb_build_object(
      'id',v_member.id,
      'display_name',v_member.display_name,
      'role',v_role,
      'is_super_admin',v_is_super_admin,
      'changed',false
    );
  end if;

  update public.coaching_members
  set role=v_role,
      is_super_admin=v_is_super_admin,
      updated_at=now()
  where id=v_member.id;

  insert into public.coaching_audit_events(
    workspace_id,
    actor_member_id,
    action,
    changes
  )
  values(
    v_actor.workspace_id,
    v_actor.id,
    'coach_role_changed',
    jsonb_build_object(
      'member_id',v_member.id,
      'from_role',v_old_role,
      'to_role',v_role,
      'from_is_super_admin',v_old_is_super_admin,
      'to_is_super_admin',v_is_super_admin
    )
  );

  return jsonb_build_object(
    'id',v_member.id,
    'display_name',v_member.display_name,
    'role',v_role,
    'is_super_admin',v_is_super_admin,
    'changed',true
  );
end
$function$

CREATE OR REPLACE FUNCTION public.coach_create_participant(p_actor uuid, p_coach uuid, p_first_name text, p_last_name text, p_email text, p_phone text, p_city text DEFAULT 'Hamburg'::text, p_household_size smallint DEFAULT NULL::smallint)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_actor public.coaching_members%rowtype;
  v_user uuid;
  v_public_id text;
  v_email text;
  v_phone text;
begin
  select * into v_actor
  from public.coaching_members
  where id=p_actor and is_active
  for share;

  if not found then raise exception 'actor_forbidden'; end if;

  if not exists(
    select 1 from public.coaching_workspaces
    where id=v_actor.workspace_id and is_active and not operations_paused
  ) then raise exception 'workspace_unavailable'; end if;

  if p_coach is distinct from v_actor.id and v_actor.role<>'admin' then
    raise exception 'admin_required';
  end if;

  if (p_coach is null and v_actor.role<>'admin') or (p_coach is not null and not exists(
    select 1 from public.coaching_members
    where id=p_coach and workspace_id=v_actor.workspace_id and is_active and role in ('coach','admin') for share
  )) then raise exception 'coach_unavailable'; end if;

  if nullif(btrim(p_first_name),'') is null
     or nullif(btrim(p_last_name),'') is null
  then raise exception 'participant_fields_required'; end if;

  v_email:=nullif(lower(btrim(coalesce(p_email,''))),'');
  if v_email is not null and v_email !~* '^[^[:space:]@]+@[^[:space:]@]+[.][^[:space:]@]+$' then
    raise exception 'invalid_email';
  end if;
  v_phone:=nullif(btrim(coalesce(p_phone,'')),'');

  insert into public.bot_users(
    telegram_user_id,chat_id,first_name,last_name,is_active,origin,plan_override
  )
  values(null,null,btrim(p_first_name),btrim(p_last_name),true,'coaching','free')
  returning id into v_user;

  insert into public.applicant_profiles(
    user_id,first_name,last_name,email,phone,city,household_size
  )
  values(
    v_user,btrim(p_first_name),btrim(p_last_name),v_email,
    v_phone,coalesce(nullif(btrim(p_city),''),'Hamburg'),p_household_size
  );

  v_public_id := 'cp_'||encode(extensions.gen_random_bytes(12),'hex');

  insert into public.coaching_participants(
    user_id,workspace_id,coach_member_id,created_by_member_id,status,public_id
  )
  values(v_user,v_actor.workspace_id,p_coach,v_actor.id,'active',v_public_id);

  insert into public.coaching_audit_events(
    workspace_id,actor_member_id,participant_user_id,action,changes
  )
  values(
    v_actor.workspace_id,v_actor.id,v_user,'participant_created',
    jsonb_build_object('coach_member_id',p_coach)
  );

  return v_user;
end
$function$

CREATE OR REPLACE FUNCTION public.coach_create_participant_idempotent(p_actor uuid, p_coach uuid, p_request_id uuid, p_first_name text, p_last_name text, p_email text, p_phone text, p_city text DEFAULT 'Hamburg'::text, p_household_size smallint DEFAULT NULL::smallint)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_actor public.coaching_members%rowtype;
  v_user uuid;
  v_existing_user uuid;
  v_existing_actor uuid;
  v_existing_workspace uuid;
  v_public_id text;
  v_claimed boolean := false;
  v_email text;
  v_phone text;
begin
  if p_request_id is null then
    raise exception 'request_id_required';
  end if;

  select * into v_actor
  from public.coaching_members
  where id=p_actor and is_active
  for share;

  if not found then raise exception 'actor_forbidden'; end if;

  if not exists(
    select 1 from public.coaching_workspaces
    where id=v_actor.workspace_id and is_active and not operations_paused
  ) then raise exception 'workspace_unavailable'; end if;

  if p_coach is distinct from v_actor.id and v_actor.role<>'admin' then
    raise exception 'admin_required';
  end if;

  if (p_coach is null and v_actor.role<>'admin') or (p_coach is not null and not exists(
    select 1 from public.coaching_members
    where id=p_coach and workspace_id=v_actor.workspace_id and is_active and role in ('coach','admin') for share
  )) then raise exception 'coach_unavailable'; end if;

  if nullif(btrim(p_first_name),'') is null
     or nullif(btrim(p_last_name),'') is null
  then raise exception 'participant_fields_required'; end if;

  v_email:=nullif(lower(btrim(coalesce(p_email,''))),'');
  if v_email is not null and v_email !~* '^[^[:space:]@]+@[^[:space:]@]+[.][^[:space:]@]+$' then
    raise exception 'invalid_email';
  end if;
  v_phone:=nullif(btrim(coalesce(p_phone,'')),'');

  insert into public.coaching_request_keys(
    request_id,workspace_id,actor_member_id,action
  )
  values(p_request_id,v_actor.workspace_id,v_actor.id,'create_participant')
  on conflict(request_id) do nothing;

  get diagnostics v_claimed = row_count;

  if not v_claimed then
    select participant_user_id,actor_member_id,workspace_id
      into v_existing_user,v_existing_actor,v_existing_workspace
    from public.coaching_request_keys
    where request_id=p_request_id;

    if v_existing_actor is distinct from v_actor.id
       or v_existing_workspace is distinct from v_actor.workspace_id then
      raise exception 'request_id_conflict';
    end if;

    if v_existing_user is not null then
      return v_existing_user;
    end if;

    raise exception 'request_in_progress';
  end if;

  insert into public.bot_users(
    telegram_user_id,chat_id,first_name,last_name,is_active,origin,plan_override
  )
  values(null,null,btrim(p_first_name),btrim(p_last_name),true,'coaching','free')
  returning id into v_user;

  insert into public.applicant_profiles(
    user_id,first_name,last_name,email,phone,city,household_size
  )
  values(
    v_user,btrim(p_first_name),btrim(p_last_name),v_email,
    v_phone,coalesce(nullif(btrim(p_city),''),'Hamburg'),p_household_size
  );

  v_public_id := 'cp_'||encode(extensions.gen_random_bytes(12),'hex');

  insert into public.coaching_participants(
    user_id,workspace_id,coach_member_id,created_by_member_id,status,public_id
  )
  values(v_user,v_actor.workspace_id,p_coach,v_actor.id,'active',v_public_id);

  update public.coaching_request_keys
  set participant_user_id=v_user
  where request_id=p_request_id;

  insert into public.coaching_audit_events(
    workspace_id,actor_member_id,participant_user_id,action,changes
  )
  values(
    v_actor.workspace_id,v_actor.id,v_user,'participant_created',
    jsonb_build_object('coach_member_id',p_coach,'request_id',p_request_id)
  );

  return v_user;
end
$function$

CREATE OR REPLACE FUNCTION public.coach_delete_participant(p_actor uuid, p_user uuid)
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_actor public.coaching_members%rowtype;
  v_assignment public.coaching_participants%rowtype;
  v_telegram_user_id bigint;
begin
  select * into v_actor
  from public.coaching_members
  where id=p_actor and is_active
  for share;
  if not found or v_actor.role not in ('coach','admin') then
    raise exception 'coach_forbidden';
  end if;
  if not exists(
    select 1 from public.coaching_workspaces
    where id=v_actor.workspace_id and is_active and not operations_paused
  ) then raise exception 'workspace_unavailable'; end if;
  select * into v_assignment
  from public.coaching_participants
  where user_id=p_user and workspace_id=v_actor.workspace_id
  for update;
  if not found then raise exception 'participant_forbidden'; end if;
  if v_actor.role<>'admin' and v_assignment.coach_member_id is distinct from v_actor.id then
    raise exception 'participant_forbidden';
  end if;
  select telegram_user_id into v_telegram_user_id
  from public.bot_users
  where id=p_user
  for update;
  if not found then raise exception 'participant_forbidden'; end if;

  if v_telegram_user_id is not null then
    insert into public.coaching_audit_events(
      workspace_id,actor_member_id,participant_user_id,action,changes
    ) values(
      v_actor.workspace_id,v_actor.id,p_user,'participant_removed_from_portal',
      jsonb_build_object('telegram_data_preserved',true)
    );
    delete from public.coaching_participants
    where user_id=p_user and workspace_id=v_actor.workspace_id;
    return 'removed_from_portal';
  end if;

  if exists(select 1 from public.telegram_announcements where created_by=p_user) then
    raise exception 'participant_delete_restricted';
  end if;
  insert into public.coaching_audit_events(
    workspace_id,actor_member_id,participant_user_id,action,changes
  ) values(
    v_actor.workspace_id,v_actor.id,p_user,'participant_deleted',
    jsonb_build_object('telegram_data_preserved',false)
  );
  delete from public.platform_sessions where user_id=p_user;
  delete from public.bot_users where id=p_user;
  return 'deleted';
end
$function$

