CREATE OR REPLACE FUNCTION public.coach_issue_platform_connect_flow(p_actor uuid, p_user uuid, p_provider text, p_state text, p_verifier text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare v_actor public.coaching_members%rowtype; v_assignment public.coaching_participants%rowtype; v_flow public.platform_auth_flows%rowtype;
begin
  select * into v_actor from public.coaching_members where id=p_actor and is_active for share;
  if not found then raise exception 'coach_forbidden'; end if;
  if p_provider not in ('immoscout','kleinanzeigen','immomio','immowelt','wg_gesucht')
     or p_state !~ '^[A-Za-z0-9_-]{30,100}$' or p_verifier !~ '^[A-Za-z0-9_-]{43,128}$'
  then raise exception 'provider_unsupported'; end if;
  select * into v_assignment from public.coaching_participants where user_id=p_user and workspace_id=v_actor.workspace_id and status='active'
    and (v_actor.role='admin' or coach_member_id=p_actor) for update;
  if not found then raise exception 'participant_forbidden'; end if;
  if not exists(select 1 from public.coaching_workspaces where id=v_actor.workspace_id and is_active and not operations_paused)
  then raise exception 'workspace_unavailable'; end if;
  if p_provider<>'wg_gesucht' and not exists(select 1 from public.coach_effective_premium_status(array[p_user]) where is_premium)
  then raise exception 'premium_required'; end if;
  update public.platform_auth_flows set consumed_at=clock_timestamp() where user_id=p_user and provider=p_provider and consumed_at is null;
  insert into public.platform_auth_flows(user_id,provider,state,code_verifier,origin,issued_by,return_target,context,expires_at)
  values(p_user,p_provider,p_state,p_verifier,'coach',v_actor.auth_user_id,'coach',jsonb_build_object('assignment_version',v_assignment.assignment_version),clock_timestamp()+interval '30 minutes')
  returning * into v_flow;
  return jsonb_build_object('expiresAt',v_flow.expires_at);
end $function$

CREATE OR REPLACE FUNCTION public.coach_prepare_member_deletion(p_actor uuid, p_member uuid, p_target uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_actor public.coaching_members%rowtype;
  v_member public.coaching_members%rowtype;
  v_count integer;
begin
  select * into v_actor
  from public.coaching_members
  where id=p_actor and is_active
  for share;

  if not found or v_actor.role<>'admin' then
    raise exception 'admin_required';
  end if;

  if not exists(
    select 1
    from public.coaching_workspaces
    where id=v_actor.workspace_id and is_active and not operations_paused
  )
  then
    raise exception 'workspace_unavailable';
  end if;

  if p_actor=p_member or p_target=p_member then
    raise exception 'coach_unavailable';
  end if;

  select * into v_member
  from public.coaching_members
  where id=p_member
    and workspace_id=v_actor.workspace_id
    and (
      role='coach'
      or (role='admin' and v_actor.is_super_admin)
    )
  for update;

  if not found or v_member.is_super_admin then
    raise exception 'super_admin_protected';
  end if;

  if p_target is not null then
    perform 1
    from public.coaching_members
    where id=p_target
      and workspace_id=v_actor.workspace_id
      and role='coach'
      and is_active
    for share;

    if not found then
      raise exception 'coach_unavailable';
    end if;
  end if;

  update public.coaching_members
  set is_active=false,
      updated_at=now()
  where id=p_member;

  update public.coaching_participants
  set coach_member_id=p_target,
      assignment_version=assignment_version+1,
      updated_at=now()
  where workspace_id=v_actor.workspace_id
    and coach_member_id=p_member;

  get diagnostics v_count=row_count;

  update public.platform_auth_flows
  set consumed_at=coalesce(consumed_at,now())
  where issued_by=v_member.auth_user_id
    and consumed_at is null;

  update app_private.telegram_link_tokens
  set invalidated_at=coalesce(invalidated_at,now())
  where created_by=v_member.auth_user_id
    and consumed_at is null;

  update storage.objects
  set owner=v_actor.auth_user_id,
      owner_id=v_actor.auth_user_id::text
  where owner=v_member.auth_user_id
     or owner_id=v_member.auth_user_id::text;

  insert into public.coaching_audit_events(
    workspace_id,actor_member_id,action,changes
  )
  values(
    v_actor.workspace_id,
    p_actor,
    'coach_deletion_prepared',
    jsonb_build_object(
      'member_id',p_member,
      'target_member_id',p_target,
      'participants_preserved',v_count
    )
  );

  return jsonb_build_object(
    'auth_user_id',v_member.auth_user_id,
    'participants_preserved',v_count
  );
end
$function$

