CREATE OR REPLACE FUNCTION public.complete_coach_bootstrap(p_token text, p_auth_user uuid, p_display_name text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_token_id uuid;
  v_workspace uuid;
  v_member uuid;
begin
  if nullif(btrim(p_display_name),'') is null then
    raise exception 'display_name_required';
  end if;

  if exists(
    select 1 from public.coaching_members
    where role='admin' and is_active
  ) then
    raise exception 'admin_already_exists';
  end if;

  select t.id
    into v_token_id
  from app_private.coach_bootstrap_tokens t
  where t.token_hash=encode(extensions.digest(p_token,'sha256'),'hex')
    and t.consumed_at is null
    and t.expires_at>now()
  for update;

  if v_token_id is null then
    raise exception 'bootstrap_token_invalid';
  end if;

  select id into v_workspace
  from public.coaching_workspaces
  where name='NexaLabs' and is_active
  limit 1;

  if v_workspace is null then
    raise exception 'workspace_unavailable';
  end if;

  insert into public.coaching_members(
    auth_user_id,workspace_id,display_name,role,is_active
  )
  values(
    p_auth_user,v_workspace,btrim(p_display_name),'admin',true
  )
  returning id into v_member;

  update app_private.coach_bootstrap_tokens
  set consumed_at=now()
  where id=v_token_id;

  insert into public.coaching_audit_events(
    workspace_id,actor_member_id,participant_user_id,action,changes
  )
  values(
    v_workspace,v_member,null,'admin_bootstrapped','{}'::jsonb
  );

  return v_member;
end
$function$

CREATE OR REPLACE FUNCTION public.complete_platform_connect_flow(p_flow uuid, p_user uuid, p_provider text, p_claim text, p_connection jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare v_flow public.platform_auth_flows%rowtype;
begin
  select * into v_flow from public.platform_auth_flows
  where id=p_flow and user_id=p_user and provider=p_provider;
  if not found then raise exception 'auth_flow_expired'; end if;
  perform app_private.assert_platform_connect_context(v_flow);
  select * into v_flow from public.platform_auth_flows
  where id=p_flow and user_id=p_user and provider=p_provider for update;
  if not found or v_flow.consumed_at is not null or v_flow.expires_at<=clock_timestamp()
     or nullif(p_claim,'') is null
     or v_flow.context->>'completion_claim' is distinct from p_claim
  then raise exception 'auth_flow_expired'; end if;
  if nullif(p_connection->>'credential_ciphertext','') is null
     or nullif(p_connection->>'credential_iv','') is null
  then raise exception 'connection_save_failed'; end if;
  insert into public.platform_connections(
    user_id,provider,status,credential_ciphertext,credential_iv,key_version,
    account_hint,expires_at,last_verified_at,last_error,updated_at
  ) values(
    p_user,p_provider,'connected',p_connection->>'credential_ciphertext',
    p_connection->>'credential_iv',coalesce((p_connection->>'key_version')::smallint,1),
    nullif(p_connection->>'account_hint',''),
    nullif(p_connection->>'expires_at','')::timestamptz,clock_timestamp(),null,clock_timestamp()
  )
  on conflict(user_id,provider) do update set
    status='connected',credential_ciphertext=excluded.credential_ciphertext,
    credential_iv=excluded.credential_iv,key_version=excluded.key_version,
    account_hint=excluded.account_hint,expires_at=excluded.expires_at,
    last_verified_at=excluded.last_verified_at,last_error=null,updated_at=excluded.updated_at;
  update public.platform_auth_flows
  set consumed_at=clock_timestamp(),context=context||jsonb_build_object('completed_at',clock_timestamp())
  where id=p_flow;
  return true;
end $function$

CREATE OR REPLACE FUNCTION public.complete_referral_reward(p_referred_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_referral public.referrals%rowtype;
  v_referred_until timestamptz;
  v_referrer_until timestamptz;
  v_referred_chat_id bigint;
begin
  -- This operation is server-only; qualification must also hold in the DB.
  if not exists (
    select 1 from public.search_profiles where user_id = p_referred_user_id
  ) then
    return jsonb_build_object('status', 'not_qualified');
  end if;
  select * into v_referral
  from public.referrals r
  where r.referred_user_id = p_referred_user_id
    and r.status = 'registered'
  for update;

  if v_referral.id is null then
    return jsonb_build_object('status', 'none');
  end if;

  select
    greatest(now(), coalesce(u.referral_bonus_until, now())) + interval '30 days',
    u.chat_id
  into v_referred_until, v_referred_chat_id
  from public.bot_users u
  where u.id = p_referred_user_id
  for update;

  select greatest(now(), coalesce(u.referral_bonus_until, now())) + interval '30 days'
  into v_referrer_until
  from public.bot_users u
  where u.id = v_referral.referrer_user_id
  for update;

  if v_referred_until is null or v_referrer_until is null then
    return jsonb_build_object('status', 'user_not_found');
  end if;

  update public.bot_users
  set referral_bonus_until = v_referred_until,
      referral_bonus_days = referral_bonus_days + 30,
      updated_at = now()
  where id = p_referred_user_id;

  update public.bot_users
  set referral_bonus_until = v_referrer_until,
      referral_bonus_days = referral_bonus_days + 30,
      updated_at = now()
  where id = v_referral.referrer_user_id;

  update public.referrals
  set status = 'rewarded',
      qualified_at = now(),
      rewarded_at = now(),
      premium_granted_until = v_referred_until
  where id = v_referral.id;

  return jsonb_build_object(
    'status', 'rewarded',
    'referral_id', v_referral.id,
    'referrer_user_id', v_referral.referrer_user_id,
    'referred_user_id', p_referred_user_id,
    'referred_chat_id', v_referred_chat_id,
    'referred_premium_until', v_referred_until,
    'referrer_premium_until', v_referrer_until
  );
end
$function$

CREATE OR REPLACE FUNCTION public.consume_immomio_application_send(p_id uuid, p_token uuid, p_user uuid, p_listing uuid, p_source_identifier uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare n integer;
begin
 perform 1 from public.applications a where a.id=p_id for update;
 if not public.validate_immomio_application_send(p_id,p_token,p_user,p_listing,p_source_identifier) then return false; end if;
 update app_private.application_send_keys k set request_started_at=clock_timestamp()
 where k.application_id=p_id and k.user_id=p_user and k.provider='immomio' and k.source_identifier=p_source_identifier and k.request_started_at is null;
 get diagnostics n=row_count; return n=1;
end $function$

CREATE OR REPLACE FUNCTION public.deactivate_missing_source_listings(p_source_id smallint, p_keys text[])
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_count integer;
begin
  if p_source_id is null or p_keys is null then
    raise exception 'source and key array are required' using errcode='22023';
  end if;
  if cardinality(p_keys) > 10000 then
    raise exception 'snapshot key array too large' using errcode='22023';
  end if;

  update public.listings l
  set is_active = false
  where l.source_id = p_source_id
    and l.is_active = true
    and not coalesce(l.raw ? 'category_stream',false) and not (l.source_listing_key = any(p_keys));

  get diagnostics v_count = row_count;
  return v_count;
end;
$function$

CREATE OR REPLACE FUNCTION public.disconnect_ui_action(p_id uuid, p_token uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare j app_private.ui_action_jobs%rowtype;v_provider text;v_updated timestamptz;
begin
 select * into j from app_private.ui_action_jobs where id=p_id and lease_token=p_token and action='disconnect' and status='processing' and lease_until>now() for update;
 if not found then return false;end if;
 if not exists(select 1 from public.bot_users where id=j.user_id and chat_id=j.chat_id and is_active and app_private.user_is_premium(id)) then return false;end if;
 v_provider:=case j.provider when 1 then 'immoscout' when 2 then 'kleinanzeigen' else 'immomio' end;
 select updated_at into v_updated from public.platform_connections where user_id=j.user_id and provider=v_provider for update;
 if v_updated is distinct from j.connection_updated_at then return false;end if;
 delete from public.platform_connections where user_id=j.user_id and provider=v_provider;
 delete from public.platform_auth_flows where user_id=j.user_id and provider=v_provider and created_at<=j.created_at;
 return true;
end $function$

CREATE OR REPLACE FUNCTION public.dispatcher_slot(p_owner uuid, p_complete boolean DEFAULT false)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r app_private.dispatch_control%rowtype;
begin
 select * into r from app_private.dispatch_control where singleton for update;
 if r.owner is distinct from p_owner or r.expires_at<now() then raise exception 'dispatcher lease lost'; end if;
 if p_complete then
   update app_private.dispatch_control set next_send_at=clock_timestamp()+interval '15 seconds' where singleton returning next_send_at into r.next_send_at;
 end if;
 return r.next_send_at;
end $function$

CREATE OR REPLACE FUNCTION public.enqueue_ui_action(p_update_id bigint, p_attempt integer, p_user uuid, p_chat bigint, p_message bigint, p_action text, p_provider smallint)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare j uuid; connection_version timestamptz;
begin
 if not exists(select 1 from public.bot_users u join public.bot_events e on e.telegram_user_id=u.telegram_user_id where u.id=p_user and u.chat_id=p_chat and u.is_active and e.telegram_update_id=p_update_id and e.processing_status='processing' and e.processing_attempt=p_attempt and app_private.user_is_premium(u.id)) then raise exception 'ui_action_not_authorized';end if;
 select updated_at into connection_version from public.platform_connections where user_id=p_user and provider=case p_provider when 1 then 'immoscout' when 2 then 'kleinanzeigen' else 'immomio' end;
 insert into app_private.ui_action_jobs(update_id,user_id,chat_id,message_id,action,provider,connection_updated_at) values(p_update_id,p_user,p_chat,p_message,p_action,p_provider,connection_version) on conflict do nothing returning id into j;
 if j is null then select id into j from app_private.ui_action_jobs where update_id=p_update_id and action=p_action and provider=p_provider;end if;
 return j;
end $function$
